// src/streams/ibi-stream.ts
var IBIStream = class extends Stream {
  constructor(data) {
    super("IBI");
    if (data) {
      this.data = data;
    }
  }
  getStreamDataByTime(startDate, filterNull = false) {
    let time = 0;
    return this.data.reduce(
      (accu, dataItem, _index) => {
        time += dataItem;
        if (filterNull && dataItem === null) {
          return accu;
        }
        accu.push({
          time: startDate.getTime() + time,
          value: dataItem
        });
        return accu;
      },
      []
    );
  }
  //
  getStreamDataByDuration(offset, filterNull = false) {
    const data = this.data;
    let time = offset || 0;
    return data.reduce(
      (accu, dataItem, _index) => {
        time += dataItem;
        if (filterNull && dataItem === null) {
          return accu;
        }
        accu.push({
          time,
          value: dataItem
        });
        return accu;
      },
      []
    );
  }
};

